-- Normalize spacing and typo artifacts in seeded economic term descriptions.
-- Keep term names and existing term_dictionary ids unchanged for news mappings and saved terms.
UPDATE term_dictionary SET content = '국경 간 자본유출입은 기업의 자금조달 비용을 낮추어 투자를 활성화하는 긍정적인 측면도 있지만, 단기간에 대규모로 이루어질 경우 환율 또는 증권가격의 급등락을 불러와 경제 안정을 해칠 수도 있다.' WHERE term = '가변예치의무제도';
UPDATE term_dictionary SET content = '개별 금융회사의 부실 방지를 목적으로 하는 미시건전성정책(microprudential policy) 과 달리 경제 전체의 금융안정을 위해 시스템 리스크(systemic risk)를 억제하는 정책을 의미한다.' WHERE term = '거시건전성 정책';
UPDATE term_dictionary SET content = '은행의 특정 차주 등에 대한 신용공여가 과대한 경우 해당 거래상대방의 채무불이행 등의 발생 시 해당 은행의 자본건전성을 심하게 훼손할 가능성(편중리스크)이 있다.' WHERE term = '거액익스포저 규제';
UPDATE term_dictionary SET content = '제2차 세계대전 직후 유럽경제 부흥 지원을 위해 설립되었던 유럽경제협력기구(OEEC)의 18개국과 미국, 캐나다 등 총 20개 선진국이 1960년 12월에 설립한 국제기구이다.' WHERE term = '경제협력개발기구(OECD)';
UPDATE term_dictionary SET content = '군인과 재소자 등을 제외한 만15세 이상 인구를 노동가능인구라 하며, 이 중 일할 수 있는 능력과 취업의사를 동시에 갖춘 사람을 경제활동인구라 한다.' WHERE term = '경제활동인구/비경제활동인구/경제활동참가율';
UPDATE term_dictionary SET content = '복지지표로서 한계성을 갖는 국민총소득(GNI)을 보완하기 위해 미국의 노드하우스(W. Nordhaus)와 토빈(J. Tobin)이 제안한 새로운 지표를 말한다.' WHERE term = '경제후생지표';
UPDATE term_dictionary SET content = '고객확인절차(KYC; Know Your Customer)는 고객의 신원을 식별하고 확인하는(verify) 업무절차를 뜻한다.' WHERE term = '고객확인절차(KYC)';
UPDATE term_dictionary SET content = '국제노동기구(ILO)에서는 노동공급과 노동수요가 일치하지 않아서 일하고 싶은 욕구 가 있음에도 불구하고 일을 하고 있지 못하는 노동력의 크기를 나타내는 고용보조지표를 새로이 확정(2013년 10월)한 바 있다.' WHERE term = '고용보조지표';
UPDATE term_dictionary SET content = '은행은 보유하고 있는 여신을 자산건전성에 따라 5단계로 분류하여 관리하고 있다. 즉 자산건전성이 가장 양호한 상태인 정상에서부터 회수가 어려운 정도에 따라 단계적으 로 요주의, 고정, 회수의문, 추정손실 등으로 분류한다. 이 중 고정, 회수의문, 및 추정손실 로 분류된 여신의 합계액을 총여신으로 나눈 비율을 고정이하여신비율이라고 한다.' WHERE term = '고정이하여신비율';
UPDATE term_dictionary SET content = '환율제도는 고정환율제도(fixed exchange rate system)와 자유변동환율제도(free floating exchange rate system)를 양 극단으로 하여 이를 절충하는 다양한 형태로 분류될 수 있다.' WHERE term = '고정환율제도/자유변동환율제도';
UPDATE term_dictionary SET content = '구매력평가(PPP; Purchasing Power Parity) 환율은 해당 통화의 실질 구매력을 기준으 로 평가한 환율이라고 할 수 있는데, 이는 관련 당사국간 물가수준(또는 물가상승률) 차이 즉, 당사국 화폐 간 실질구매력(가치)의 차이에 의해 균형 환율이 결정된다는 구매력 평가이론에 근거하고 있다.' WHERE term = '구매력평가환율';
UPDATE term_dictionary SET content = '금융기관이 차주에 대한 여신과 연계하여 대출금액의 일부를 차주의 의사에 반하여 예적금 등으로 수취하거나 정당한 사유 없이 차주의 예적금 인출 및 해약을 제한하는 행위를 말한다.' WHERE term = '구속성예금';
UPDATE term_dictionary SET content = '노동의 수요와 공급을 나타내는 지표로 일자리 수를 취업 희망자 수로 나누어 구하는데 인력수급동향을 파악하는 데 주로 이용된다.' WHERE term = '구인배율';
UPDATE term_dictionary SET content = '2003년 1월 한국은행이 국고업무를 전자적으로 처리하기 위하여 구축한 전산망을 국고전산망이라고 말하며 정부(디지털예산회계시스템(dBrain)), 한국은행, 금융기관(우정사업본부 포함) 및 금융결제원의 전산시스템을 서버접속 방식으로 연결한다.' WHERE term = '국고전산망';
UPDATE term_dictionary SET content = '국민총소득(GNI; Gross National Income)은 한 나라의 국민이 생산활동에 참여한 대가로 받은 소득의 합계로서 외국으로부터 국민(거주자)이 받은 소득(국외수취 요소소 득)은 포함되고 국내총생산 중에서 외국인에게 지급한 소득(국외지급 요소소득)은 제외된다.' WHERE term = '국민총소득(GNI)';
UPDATE term_dictionary SET content = '개별 경제주체가 모자라는 돈을 다른 사람으로부터 조달하는 것과 마찬가지로 국민경제에서도 투자가 저축을 초과하게 되면 부족한 돈을 국외로부터 조달하게 되는데 이를 국외저축(foreign savings)이라고 한다. 국외저축은 경상수지적자와 일치하며 경상수지적자는 순국외채무(국외채무-국외 채권)의 증가로 보전된다.' WHERE term = '국외저축';
UPDATE term_dictionary SET content = '일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래에 따른 수입과 지급의 차이를 의미한다.' WHERE term = '국제수지(BOP)';
UPDATE term_dictionary SET content = '일정 기간 동안 한 나라의 거주자와 비거주자 간에 발생한 경제적 거래를 국제기준에 따라 체계적으로 기록한 표이다.' WHERE term = '국제수지표';
UPDATE term_dictionary SET content = '국제회계기준(IFRS; International Financial Reporting Standards)은 기업의 회계처리 와 재무제표에 대한 국제적 정합성을 높이기 위해서 국제회계기준위원회(IASB; International Accounting Standards Board)가 제정한 회계처리기준을 말한다.' WHERE term = '국제회계기준';
UPDATE term_dictionary SET content = '1999년 11월 미국 의회가 제정한 법으로서 공식 명칭은 금융서비스현대화법(The Financial Services Modernization Act of 1999)이다.' WHERE term = '그램-리치-블라일리법';
UPDATE term_dictionary SET content = '집합투자기구(MMF 채권형 혼합형 펀드 등), RP 거래, 유동화기구 등과 같이 은행시 스템 밖에서 신용중개기능을 수행하지만 은행 수준의 건전성 규제와 예금자보호가 적용되지 않는 기관 또는 활동을 이르는 용어이다.' WHERE term = '그림자 금융';
UPDATE term_dictionary SET content = '미국 의회가 제정한 법으로 공식 명칭은 1933년 은행법(Banking Act of 1933)이다.' WHERE term = '글래스-스티걸법';
UPDATE term_dictionary SET content = '금융위기 등으로 인하여 외화유동성이 부족해지는 경우에 대비하기 위하여 각국이 외화유동성을 인출하거나 지원받는 각종 제도적 장치들을 총칭하여 글로벌금융안전망이라고 한다.' WHERE term = '글로벌금융안전망';
UPDATE term_dictionary SET content = '금리선물(interest rate futures)이란 기초자산인 금리를 거래대상으로 하며 현재의 시점에서 정한 가격으로 미래의 특정 시점에서 사거나 팔 것을 약정하는 계약을 말한다.' WHERE term = '금리선물';
UPDATE term_dictionary SET content = '금리스왑(IRS; Interest Rate Swaps)이란 금리변동위험 헤지 및 차입비용 절감 등을 위하여 거래당사자 간에 원금교환 없이 정기적(3개월)으로 변동금리(91일물 CD금리) 와 고정금리(IRS금리)를 교환하는 거래를 말한다.' WHERE term = '금리스왑';
UPDATE term_dictionary SET content = '경제주체의 위험추구 성향, 신용담보로 제공되는 실물자산의 가치변동 등이 상호작용하면서 나타나는 금융변수들의 종합적인 순환변동을 의미한다.' WHERE term = '금융사이클';
UPDATE term_dictionary SET content = '금융불안을 초래할 수 있는 시스템 리스크는 시계열 차원뿐만 아니라 특정 시점에서 종합적으로 파악할 필요가 있는데, 특정 시점에서 시스템 리스크를 초래할 수 있는 핵심 요인인 상호연계성은 해당 금융업권(기관)이 영업활동 과정에서 여타 금융업권(기관)과 밀접하게 연결된 정도를 의미한다.' WHERE term = '금융시스템 상호연계성';
UPDATE term_dictionary SET content = '핀테크의 발달에 따라 금융업의 분화 현상이 심화됨으로써 금융서비스가 탈중개화(disintermediation)되고 탈집중화(decentralization)되는 경향을 보인다.' WHERE term = '금융의 탈중개화';
UPDATE term_dictionary SET content = '예를 들면, 대출 분야의 경우 지점을 갖지 않는 인터넷전문은행이 인터넷(모바일) 금융서비스 분야에 새로 진입하여 획기적으로 단기간에 대규모 고객을 확보함에 따라, 기존 대형 은행들이 대출금리 하향 조정 압력을 받게 됨은 물론 은행 내부에서 인터넷(모바일)뱅킹사업 분야의 조직이 나 인원을 별도로 강화할 수밖에 없게 되었다.' WHERE term = '금융의 탈집중화';
UPDATE term_dictionary SET content = '금융거래에 관한 체계와 규범을 총칭하는 개념으로 금융시장, 금융기관, 금융기반구조(infra-structure)로 구분된다.' WHERE term = '금융제도';
UPDATE term_dictionary SET content = '기업 개인 간(B2C) 지급결제시스템은 기업 간(B2B) 지급결제시스템과는 달리 특정 지급결제시스템을 지칭하는 것이 아니라 인터넷쇼핑몰 등의 전자상거래에서 이루어지 는 판매자 및 구매자 간의 소액결제에 이용되는 지급결제시스템을 통칭하는 용어이다.' WHERE term = '기업 개인간(B2C) 지급결제시스템';
UPDATE term_dictionary SET content = '기업 간(B2B) 지급결제시스템은 전자외상매출채권(전자채권)의 발행과 만기 시 결제를 처리하는 시스템으로 2002년 3월 가동되었다.' WHERE term = '기업간(B2B) 지급결제시스템';
UPDATE term_dictionary SET content = '기초가격(basic price)은 일정 기간 동안 경제주체가 생산한 생산물을 가격으로 평가함 에 있어 생산자가격에서 부가가치세와 같은 생산물세(production tax)를 제외하고 정부 에서 주는 보조금(subsidy)을 더한 가격을 의미하며, 순수하게 생산자(주로 기업) 가 갖게 되는 몫을 말한다.' WHERE term = '기초가격';
UPDATE term_dictionary SET content = '경기과열 우려가 있는 경우에 재정 또는 통화정책으로 국민의 소득을 감소시켜 재화 및 서비스에 대한 수요를 위축시키고 경기의 과열을 방지하려는 정책을 긴축정책(contractionary policy)이라고 한다.' WHERE term = '긴축정책';
UPDATE term_dictionary SET content = '범죄학의 낙인이론에 따르면 일탈 또는 범죄행동은 관련 주체의 독자적 행동에 의해서도 발생하지만, 해당 행동에 대한 사회적 평가 또는 해당 행동을 한 주체의 사회적 소외의 결과로도 발생할 수 있다.' WHERE term = '낙인효과';
UPDATE term_dictionary SET content = '단리(simple interest)는 원금에 대해서만 약정된 이율과 기간을 곱하여 이자를 산출하는 방식이다.' WHERE term = '단리/복리';
UPDATE term_dictionary SET content = '경쟁입찰에 따른 발행금리 결정방식에는 복수금리(conventional)방식과 단일금리(dutch)방식이 있다.' WHERE term = '단일금리방식/복수금리방식';
UPDATE term_dictionary SET content = '현물환거래의 결제는 거래당사자 상호 간에 신용위험을 회피하기 위하여 거래계약일 과 동일한 날짜에 결제가 이루어지는 것을 원칙으로 하고 있다.' WHERE term = '당일결제/익일결제/익익일결제';
UPDATE term_dictionary SET content = '독점(monopoly)은 완전경쟁의 정반대인 시장형태로 어느 기업이 시장의 유일한 공급자로 그 기업이 공급하는 상품에 밀접한 대체재가 존재하지 않는 경우를 말한다.' WHERE term = '독점/과점';
UPDATE term_dictionary SET content = '회원 간 정보 및 의견교환, 공동 관심분야에 대한 조사연구 및 연수활동을 주요 기능으로 하는 동남아 중앙은행들의 협력체로서 1966년 2월 동남아 7개국 주도로 출범하였다.' WHERE term = '동남아중앙은행기구(SEACEN)';
UPDATE term_dictionary SET content = '1997년 태국을 시작으로 인도네시아, 말레이시아, 필리핀, 한국 등 동아시아 국가들에서 발생한 외환위기를 말한다.' WHERE term = '동아시아 외환위기';
UPDATE term_dictionary SET content = 'EMEAP(Executives'' Meeting of East Asia and Pacific Central Banks)는 동아시아, 태평양 지역 내 중앙은행 간의 협력을 증진하고 회원국의 금융 경제에 관한 정보교환을 위해 1991년 설립된 중앙은행간 협력체이다.' WHERE term = '동아시아 태평양중앙은행기구(EMEAP)';
UPDATE term_dictionary SET content = '특정인에 대한 금융기관의 여신 편중을 억제하기 위한 규제로 우리나라의 경우 은행법에 관련 내용이 규정되어 있다.' WHERE term = '동일인 신용공여한도제(동일인 여신한도제)';
UPDATE term_dictionary SET content = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여 경기종합지수를 작성한다.' WHERE term = '동행종합지수';
UPDATE term_dictionary SET content = '등록발행이란 채권을 실물발행(physical issue) 하지 않고 한국예탁결제원 등 등록기 관이 관리하는 채권등록부에 채권자의 성명, 주소, 채권금액 등 권리내역을 등록(book-entry)함으로써 증서의 점유 없이도 채권자의 법적 권리를 보장하는 것을 말한다.' WHERE term = '등록발행';
UPDATE term_dictionary SET content = '디커플링(decoupling)이란 탈동조화라고 번역할 수 있는데, 어떤 나라나 지역의 경제가 인접한 다른 국가나 전반적인 세계 경제의 흐름과는 다른 모습을 보이는 현상을 말한다.' WHERE term = '디커플링/커플링';
UPDATE term_dictionary SET content = '미국의 경제학자 래퍼(A. Laffer)가 제시한 조세수입과 세율 간의 관계를 나타낸 곡선을 말한다.' WHERE term = '래퍼곡선';
UPDATE term_dictionary SET content = 'EC(유럽공동체)가 시장 통합을 넘어 정치 경제적 통합체로 결합하는 토대가 된 조약이다.' WHERE term = '마스트리히트조약';
UPDATE term_dictionary SET content = '현실적으로 다양한 종류의 채권이 발행되고 있으나 일정한 시기마다, 예컨대 3개월마다, 이자를 지급하는 이표채(coupon bond)가 가장 보편적인 것이라고 할 수 있겠다.' WHERE term = '만기수익률';
UPDATE term_dictionary SET content = '기회비용은 어떤 것을 선택할 때 포기하여야 하는 비용을 말하지만, 매몰비용(sunk cost)은 무엇을 선택하는가에 상관없이 지급할 수밖에 없는 비용이다.' WHERE term = '매몰비용';
UPDATE term_dictionary SET content = '모기지대출(mortgage loan)은 은행이 대출 실행 시 담보물인 주택 등 부동산에 주택저당채권(mortgage)을 설정하고 이를 근거로 하는 증권을 발행, 유통시켜 대출자금을 회수하는 것을 말한다.' WHERE term = '모기지대출';
UPDATE term_dictionary SET content = '모바일뱅킹 서비스는 고객이 휴대전화 등 모바일기기를 수단으로 무선인터넷을 통하여 금융기관에 접속하여 이용할 수 있는 금융서비스이다.' WHERE term = '모바일뱅킹';
UPDATE term_dictionary SET content = '물가안정목표제(inflation targeting)란 중앙은행이 명시적인 중간목표(intermediate target) 없이 일정기간 동안 또는 중장기적으로 달성해야 할 물가상승률 목표치를 미리 제시하고 이에 맞추어 통화정책을 운영하는 방식이다.' WHERE term = '물가안정목표제';
UPDATE term_dictionary SET content = '시장에서 거래되는 여러 가지 상품과 서비스의 가격을 경제생활에서 차지하는 중요도 를 고려하여 평균한 종합적인 가격수준을 물가라고 하는데, 이 같은 물가의 변화를 한눈에 알아볼 수 있도록 기준연도의 물가수준을 100으로 놓고 비교되는 다른 시점의 물가를 지수의 형태로 나타낸 것을 말한다.' WHERE term = '물가지수';
UPDATE term_dictionary SET content = '페그제도란 자국통화를 외국의 단일통화나 복수의 통화바스켓에 연동시켜 고정환율을 유지하는 제도이다.' WHERE term = '미달러화페그제도';
UPDATE term_dictionary SET content = '발행시장(primary market)이란 주식이나 채권 등의 유가증권을 신규로 발행하는 시장을 말한다.' WHERE term = '발행시장';
UPDATE term_dictionary SET content = '발행중지화폐는 발권기관인 한국은행이 화폐의 원활한 유통 등을 위해 발행을 중지하기로 한 화폐이다.' WHERE term = '발행중지화폐/유통정지화폐';
UPDATE term_dictionary SET content = '각종 법률 위반이나 법률 제정 개정 등에 대한 인식 부족, 부적절하거나 부정확한 법률 자문 및 서류 작성, 미흡한 법률체계 또는 법적 불확실성 등으로 인해 발생하는 리스크를 말한다. 특히 자국 이외의 국가에서 경영활동을 할 때 현지국가의 법률이나 법률체계를 정확히 알지 못해 동 리스크에 직면할 가능성이 커진다. 변동금리부채권(FRN)' WHERE term = '법률리스크';
UPDATE term_dictionary SET content = '변동금리란 시장금리를 반영하여 일정 주기별로 약정금리가 변하는 금리를 의미하며 고정금리란 최초 약정한 금리가 만기 때까지 그대로 유지되는 금리를 의미한다.' WHERE term = '변동금리';
UPDATE term_dictionary SET content = '보기화폐는 은행권 및 주화의 모양, 크기, 손상 정도, 위·변조 판단, 전시 및 연구실험 등을 위해 별도 제조하거나 사용중인 화폐에서 채취한 화폐를 말한다.' WHERE term = '보기화폐(견양화폐)';
UPDATE term_dictionary SET content = '보통주자본(CET1; Common Equity Tier 1)은 보통주, 자본잉여금, 이익잉여금, 기타포괄손익누계액 등으로 구성된다.' WHERE term = '보통주자본(Common Equity Tier 1)';
UPDATE term_dictionary SET content = '복수통화바스켓제도란 자국과 교역비중이 큰 복수국가의 통화를 선택하여 통화군(basket)을 구성하고 동 basket을 구성하는 통화들의 가치가 변동할 경우 각 통화별 교역가중치에 따라 자국통화의 환율에 반영하는 환율 제도를 말한다.' WHERE term = '복수통화바스켓제도';
UPDATE term_dictionary SET content = '금융회사 부실자산 등의 효율적 처리 및 한국자산관리공사의 설립에 관한 법률 (''97.8.22일 제정) 제38조에 의거 금융기관이 보유하고 있는 부실채권의 효율적인 정리를 위하여 한국자산관리공사에 한시적(5년)으로 설치 운용하였다. 2013.2.22일자로 종료되었다.' WHERE term = '부실채권정리기금';
UPDATE term_dictionary SET content = '분리결제(free of payment)는 증권결제에서 증권인도와 대금지급이 동시에 이루어지지 않고 개별적으로 이루어지는 방식이다.' WHERE term = '분리결제';
UPDATE term_dictionary SET content = '수출입거래나 국경 간 자본유출입거래는 국내은행을 통해 국내통화로 전환되며 이에 따라 국내통화량이 변동하게 된다.' WHERE term = '불태화정책';
UPDATE term_dictionary SET content = '1944년 7월 미국의 뉴햄프셔주 브레튼우즈에서 44개 연합국 대표들이 새로운 국제통화제도 구축을 위해 체결한 협정에 따라 발족한 국제통화체제를 말한다.' WHERE term = '브레튼우즈체제';
UPDATE term_dictionary SET content = '블록체인(block chain)은 ① 일정 시간 동안 발생한 모든 거래정보를 블록(block) 단위로 기록하여 ② 모든 구성원들에게 전송하고 ③ 블록의 유효성이 확보될 경우 이 새 블록을 ④ 기존의 블록에 추가 연결(chain)하여 보관하는 방식의 알고리즘이다.' WHERE term = '블록체인';
UPDATE term_dictionary SET content = '비관측경제(NOE; Non-observed Economy)란 합법적이건 불법적이건 모든 경제적 거래에서 발생한 소득을 포함해야 하는 국내총생산(GDP)의 추계시 이용되는 기초자료와 행정자료가 지하경제나 불법생산 등을 반영하기가 어려워 누락된 경제활동을 의미한 다.' WHERE term = '비관측경제(NOE)';
UPDATE term_dictionary SET content = '빅데이터(big data)란 복잡하고 다양한 대규모 데이터세트 자체는 물론 이 데이터세트로부터 정보를 추출하고 결과를 분석하여 더 큰 가치를 창출하는 기술을 뜻한다.' WHERE term = '빅데이터';
UPDATE term_dictionary SET content = '정보통신기술의 발달로 기업경영활동에서 디지털화가 가속화되고 상호 연결이 확대되어 감에 따라 전자상거래나 정보통신기술을 이용하여 이루어지는 활동 중 사이버 상에서 발생하는 예기치 못한 사고로 인해 기업이 부담하게 될 유·무형의 비용이 증가하는 위험을 말한다.' WHERE term = '사이버리스크';
UPDATE term_dictionary SET content = '4차 산업혁명(4IR; Fourth Industrial Revolution)은 18세기 초 산업혁명 이후 진행되어 온 4차 주요 산업시대로서, 2010년대부터 물리적, 디지털 및 생물학적 세계가 융합되어 모든 학문 경제 산업 등에 전반적으로 충격을 주게 된 새로운 기술영역의 등장을 뜻한다.' WHERE term = '4차 산업혁명';
UPDATE term_dictionary SET content = '사회보험(social insurance)이란 국민에게 발생 가능한 각종 사회적 위험에 보험방식을 통해 대처함으로써 국민의 생활, 건강, 소득 등을 보장하려는 제도를 가리킨다.' WHERE term = '사회보험';
UPDATE term_dictionary SET content = '일정기간(보통1년) 동안 국민경제 내에서 발생하는 재화와 서비스의 생산 및 처분과 관련된 모든 거래내역을 일정한 원칙과 형식에 따라 기록한 종합적인 통계표이다.' WHERE term = '산업연관표(I/O Tables)';
UPDATE term_dictionary SET content = '상계관세(countervailing duties)는 수출국이 수출기업에 보조금이나 장려금을 지급하여 지나치게 낮은 가격을 책정할 경우 수입국이 이로 인한 경쟁력 저하를 상쇄하기 위해 부과하는 것을 말한다.' WHERE term = '상계관세';
UPDATE term_dictionary SET content = '상시감시는 감독당국이 평상 시 은행의 영업실적 및 재무상태에 관한 보고서를 징구, 분석하는 등 전반적인 은행의 경영상황을 파악하기 위한 감독수단의 하나이다.' WHERE term = '상시감시제도/상시감시전담데스크';
UPDATE term_dictionary SET content = '1989년 7월 설립된 상품공동기금(CFC; Common Fund for Commodities)은 1차산품의 수급 안정을 위한 국제협력 증진과 국제상품협정 체결 촉진 및 기능 활성화를 목적으로 하고 있다.' WHERE term = '상품공동기금(CFC)';
UPDATE term_dictionary SET content = '국내시장의 제1차 거래단계에서 기업 상호 간에 거래되는 상품과 서비스의 평균적인 가격변동을 측정하기 위하여 작성되는 물가지수로서 그 대상품목의 포괄범위가 넓어 전반적인 상품과 서비스의 수급 동향이 반영된 일반적인 물가수준의 변동을 측정할 수 있기 때문에 일반목적지수로서의 성격을 갖는다.' WHERE term = '생산자물가지수(PPI)';
UPDATE term_dictionary SET content = '과열된 전기회로를 차단하는 안전장치에서 유래된 용어로 주식시장에서 주가의 급등락 시 주식거래를 일시 정지시켜 시장에 미치는 충격을 완화하기 위해 도입된 제도이다.' WHERE term = '서킷브레이커';
UPDATE term_dictionary SET content = '선물거래(futures transactions)란 공인된 거래소에서 품질, 규격 등이 표준화된 상품의 매매계약을 체결하고 일정 기간이 경과한 후에 상품의 인수도와 결제가 이루어지는 거래로서 매매계약의 성립과 동시에 상품의 인수도와 결제가 이루어지는 현물거래와 구분된다.' WHERE term = '선물거래';
UPDATE term_dictionary SET content = '선불형카드는 이용고객이 전자적 또는 자기적 방법으로 일정금액을 저장한 카드를 카드발행자로부터 구입하여 상품구매 또는 서비스 이용 시마다 대금이 자동으로 차감 지급되도록 한 카드로서 사용범위에 따라 범용 선불형카드와 단일목적 선불형카드로 구분된다.' WHERE term = '선불카드/선불전자지급수단';
UPDATE term_dictionary SET content = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여 경기종합지수를 작성한다.' WHERE term = '선행종합지수';
UPDATE term_dictionary SET content = '세계은행그룹(World Bank Group)을 구성하는 기구 중에서 국제부흥개발은행(IBRD) 과 국제개발협회(IDA)를 합쳐서 부르는 명칭이다.' WHERE term = '세계은행(World Bank)';
UPDATE term_dictionary SET content = '소득분배의 불평등도를 나타내는 지표의 하나로 전체 가구를 소득수준의 순서에 따라 20%씩 5등분으로 나눈 다음, 소득 상위 20%(5분위) 계층의 평균소득을 소득 하위 20%(1분위) 계층의 평균소득으로 나눈 값이다. 소득 5분위 배율 값이 커질수록 고소득층과 저소득층 간의 소득분배가 악화하였음을 의미한다.' WHERE term = '소득5분위배율';
UPDATE term_dictionary SET content = '소득교역조건지수는 순상품교역조건에 수출물량지수를 곱하여 {(수출단가지수/수입단가지수)×수출물량지수} 산출하는 것으로서 수출 금액으로 수입을 늘릴 수 있는 능력을 측정하는 지표이다. 소득교역조건지수가 상승하였다면 금기의 수출총액으로 수입할 수 있는 능력(수량)이 좋아졌다는 것을 의미한다.' WHERE term = '소득교역조건/소득교역조건지수';
UPDATE term_dictionary SET content = '소득주도성장(income-led growth)을 주장하는 학자들은 소득분배를 간과해 온 기존의 경제모델을 비판하면서 소득의 형평성이 경제의 성장과 안정성에 긴요하다는 점을 중시한다.' WHERE term = '소득주도성장';
UPDATE term_dictionary SET content = '소비행태를 설명하는 상대소득가설은 소비가 현재소득 이외에도 과거의 최고 소득수준 또는 타인의 소비수준과 같은 상대적인 요인에 의해서도 영향을 받을 수 있다는 가능성을 고려한다.' WHERE term = '소비의 비가역성';
UPDATE term_dictionary SET content = '소비자의 경기나 생활형편 등에 대한 주관적인 판단과 전망, 미래의 소비지출계획 등을 설문조사를 통해 지수화한 것으로, 기업들의 경제를 보는 시각이 반영된 기업경기실사지수(BSI; Business Survey Index)와 함께 대표적인 경제심리지수 중 하나이다.' WHERE term = '소비자동향지수(CSI)';
UPDATE term_dictionary SET content = '소비자를 대상으로 경기에 대한 판단이나 전망 등을 조사하여 지수화한 경제심리지표를 말한다.' WHERE term = '소비자심리지수';
UPDATE term_dictionary SET content = '소액결제시스템(retail payment system)은 주로 기업이나 개인의 소액거래를 처리하는 자금결제시스템으로서 주로 계좌이체나 지급카드, 수표, 지로 등과 관련된 결제가 소액결제시스템으로 처리된다.' WHERE term = '소액결제시스템';
UPDATE term_dictionary SET content = '최종수요가 한 단위 증가할 때 각 산업부문에서 직 간접으로 유발되는 수입액 단위를 말하는 것으로 형태에 따라 산업별 수입유발계수와 최종수요항목별 수입유발계수로 나뉜다. 산업별 수입유발계수는 수입투입계수표에 생산유발계수표를 곱하여 구하고 최종수요 항목별 수입유발계수는 소비, 투자, 수출 등 항목별 최종수요에 의한 수입유발액을 최종수요액으로 나누어 산출한다.' WHERE term = '수입유발계수';
UPDATE term_dictionary SET content = '국고금의 수입과 지출은 일정한 요식행위인 국가기관의 명령행위에 의하여 이루어지는데, 이러한 국고금의 수입과 지출행위를 결정(명령)하는 국가회계기관은 국고금의 종류에 따라 다양하나 크게 수입을 담당하는 수입징수관과 지출을 담당하는 지출관으로 구분한다.' WHERE term = '수입징수관/지출관';
UPDATE term_dictionary SET content = '무역지수 중 수출입물량의 변동을 나타내 주는 것으로 수출입금액지수를 수출입물가지수로 나누어 사후적으로 산출되는데 이러한 방식으로 산출되는 것은 수출입금액이 단가 요인과 물량요인의 합과 일치한다는 점에서 타당성을 가진다고 할 수 있다.' WHERE term = '수출입물량지수';
UPDATE term_dictionary SET content = '2008년 글로벌 금융위기 시 신용경색으로 금융시장 기능이 마비되면서 자금조달이나 만기연장이 어려워짐에 따라 많은 은행들이 만기불일치 등에 따른 유동성 위기를 경험하였고 이는 금융시스템 전체의 유동성 경색을 유발하였다.' WHERE term = '순안정자금조달비율';
UPDATE term_dictionary SET content = '은행의 모든 금리부자산의 운용결과로 발생한 은행의 운용자금 한 단위당 이자순수익(운용수익률)을 나타내는 개념이다. 이는 이자자산순수익(이자수익자산 운용수익 이자비용부채 조달비용)을 이자수익자산의 평잔으로 나누어 계산하는 은행의 핵심 수익성 지표이다.' WHERE term = '순이자마진(NIM)';
UPDATE term_dictionary SET content = '순이체한도제(net debit caps)는 금융결제원의 차액결제시스템에 참가하고 있는 각 참가기관으로 하여금 여타 참가기관과의 CD, 타행환 거래 등에서 발생하는 순이체액(지급지시송신액 - 지급지시수신액)에 대하여 그 상한을 설정토록 함으로써 결제불이행 사태의 발생 가능성 및 불이행 규모를 최소화하도록 한 제도이다.' WHERE term = '순이체한도제';
UPDATE term_dictionary SET content = '우리나라는 자유변동환율제도를 채택하고 있어서 환율이 원칙적으로 외환시장에서 자율적으로 결정되도록 하고 있으나, 일시적인 수급불균형이나 시장 불안심리 등으로 환율이 급변동하는 경우에 한해 외환당국이 외환시장에 개입하여 환율변동 속도를 조절하게 되는데 이를 스무딩오퍼레이션(smoothing operation)이라 한다.' WHERE term = '스무딩오퍼레이션';
UPDATE term_dictionary SET content = '거래 쌍방이 미리 정한 계약조건에 따라 현재시점에서 원금, 이자 등을 서로 교환하기로 하고 일정 기간 동안 주기적으로 원금이나 이자지급 등 현금흐름(cash flow)을 서로 교환하는 거래를 말한다.' WHERE term = '스왑';
UPDATE term_dictionary SET content = '외환스왑시장의 가격변수인 스왑레이트(swap rate)는 현물환율 대비 선물환율과 현물환율의 차이(=(선물환율-현물환율)/현물환율)를 연율(%)로 표시한 것으로 이론적으로는 양 통화 간 금리차와 일치(covered interest rate parity)하게 된다.' WHERE term = '스왑레이트';
UPDATE term_dictionary SET content = '무디스, 피치와 함께 세계 3대 국제신용평가기관으로 불리는 미국의 신용평가회사로서 1860년 Henry Varnum Poor가 설립한 Poor''s라는 투자정보서비스 회사와 1916 년 설립된 Standard의 두 회사가 1942년 합병하여 Standard & poor''s로 출범하였다.' WHERE term = '스탠더드 & 푸어스';
UPDATE term_dictionary SET content = '규모가 크고 금융시스템 내 상호연계성이 높아 부실화 또는 도산 시 금융시스템에 광범위하고 중대한 영향을 미칠 수 있는 은행, 보험사 및 여타 금융기관을 의미한다.' WHERE term = '시스템적으로 중요한 금융기관';
UPDATE term_dictionary SET content = '금융시장의 금리, 주가, 환율 등의 변동으로 은행이 단기매매를 위해 트레이딩계정(trading book)에 보유한 금융상품의 가격이 하락하여 손실이 발생할 가능성을 의미한 다.' WHERE term = '시장리스크';
UPDATE term_dictionary SET content = '우리나라가 1990년 3월 국내 외환시장의 활성화와 자본 및 금융의 국제화를 촉진시키기 위한 환율제도의 단계적 개편방안의 일환으로 도입한 제도로서, 1997년 외환위기 이전까지 시행되었다.' WHERE term = '시장평균환율제도';
UPDATE term_dictionary SET content = '신용레버리지란 레버리지효과를 거두기 위해 경제주체가 활용하고 있는 신용의 정도를 의미한다.' WHERE term = '신용레버리지';
UPDATE term_dictionary SET content = '신용스프레드란 특정 채권의 신용위험이 어느 정도인지를 보여주는 지표로서 동일만기 무위험 채권인 국고채 금리와 해당 채권 금리의 차이로 나타난다.' WHERE term = '신용스프레드';
UPDATE term_dictionary SET content = '신용창조(credit creation)는 일반적으로 은행이 예금과 대출업무를 반복적으로 취급하는 과정에서 예금통화를 만들어내는 현상을 말한다.' WHERE term = '신용창조';
UPDATE term_dictionary SET content = '넓은 의미에서 신용평가란 자금을 빌리는 차입자, 즉 가계 기업 등의 부채 상환능력이나 신용도를 일정한 등급으로 평가하는 것을 말한다.' WHERE term = '신용평가제도';
UPDATE term_dictionary SET content = '매장량이 한정되어 있는 기존의 화석연료(석유, 석탄, 천연가스 등)와 우라늄을 대체할 수 있는 에너지를 지칭하는 것으로, 새로운 기술을 활용한 에너지 또는 재생 가능한(renewable) 에너지를 포함한다.' WHERE term = '신 재생에너지';
UPDATE term_dictionary SET content = '신주인수권부사채(Bond with Warrant)는 채권을 발행한 회사가 주식을 발행할 경우 투자자가 미리 약정된 가격에 일정한 수량의 신주(新株)를 인수할 수 있는 권리인 워런트(Warrant)가 결합된 회사채를 말한다.' WHERE term = '신주인수권부사채(BW)';
UPDATE term_dictionary SET content = '미국 유럽 일본 등 신용등급이 높은 국가들이 발행한 채권에 주로 투자하는 펀드를 글로벌채권펀드, BRICs 등 신흥시장 국가들이 발행한 채권에 주로 투자하는 펀드를 신흥시장국채권펀드라고 하는데, 양자 간 투자위험도의 차이 때문에 통상 후자의 금리(투자수익률)는 전자의 금리보다 높다.' WHERE term = '신흥시장국채권지수(EMBI+)';
UPDATE term_dictionary SET content = '실업률갭은 노동시장의 여력(slack)을 평가할 수 있는 유용한 지표로, 잠재GDP와 실제GDP의 차이인 GDP갭과 함께 경기수준 또는 경제 전반의 유휴자원을 파악할 때 유용하다.' WHERE term = '실업률갭';
UPDATE term_dictionary SET content = '근로자가 노동의 대가로 받는 임금을 현재의 화폐단위로 표시한 것을 명목임금이라고 하는데 이러한 명목임금으로 재화와 서비스를 실제 구입할 수 있는 수량 즉, 구매력을 측정하기 위해 명목임금을 소비자물가지수로 나눈 것을 실질임금이라고 한다. 물가상승률이 명목상승률보다 더 높으면 실질임금은 오히려 줄어들어 실제 구매력은 감소하게 된다.' WHERE term = '실질임금';
UPDATE term_dictionary SET content = '아세안(ASEAN) 10개국, 한국, 중국 및 일본이 치앙마이 이니셔티브 다자화 협정(CMIM; Chiang Mai Initiative Multilateralization)의 효과적인 운영을 지원하기 위하여 2011년에 설립한 기구로서 싱가포르에 본부를 두고 있다.' WHERE term = '아세안+3 거시경제조사기구(AMRO)';
UPDATE term_dictionary SET content = '아시아 및 태평양 연안 국가 간의 경제협력을 목표로 설립된 국제기구로서 1989 년 11월 호주 캔버라에서 개최된 제1차 각료회의를 통하여 공식 출범하였다.' WHERE term = '아시아태평양경제협력체(APEC)';
UPDATE term_dictionary SET content = '농업이라는 뜻의 Agriculture와 인플레이션(inflation)의 합성어로 농산물 가격의 급격한 상승이 일반 물가의 상승을 일으키는 현상을 말한다.' WHERE term = '애그플레이션';
UPDATE term_dictionary SET content = '어음교환이란 다수의 은행이 일정한 시간에 특정 장소에 모여 자행이 수납한 어음(수표 및 제 증서 포함) 중 다른 은행을 지급지로 하는 어음과 다른 은행이 수납한 어음 중 자행을 지급지로 하는 어음을 서로 교환하고, 이에 따른 대금을 결제하는 것을 말하며 어음교환이 이루어지는 장소를 어음교환소라 한다.' WHERE term = '어음교환';
UPDATE term_dictionary SET content = '각종 재해나 비상사태의 발생 시에도 조직의 업무나 대고객서비스가 중단 없이 지속될 수 있도록 하거나 업무 중단에 대한 신속한 대응 및 복구를 목표로 하는 일련의 대책을 의미한다.' WHERE term = '업무지속계획';
UPDATE term_dictionary SET content = '금융감독당국이 특정 분야에 과도하게 자금을 지원하지 않도록 금융기관에게 대출 취급 시 지키도록 권고하는 지침으로, 주택경기 과열 양상과 투기수요가 늘어나면서 가계부채가 급증하는 모습을 보이자 부동산시장에 유입되는 자금의 제한을 통해 투기수요를 잠재우고 가계부채의 증가를 억제하기 위한 취지에서 도입한 것이다.' WHERE term = '여신심사 가이드라인';
UPDATE term_dictionary SET content = '펀드는 근거법률에 따라 역외펀드(off-shore fund)와 역내펀드(on-shore fund)로 구분되는데 역외펀드는 외국의 법률에 의하여 외국에서 설정, 설립된 것으로 외국펀드라고도 한다.' WHERE term = '역외펀드';
UPDATE term_dictionary SET content = '무역대금은 약정된 물품이 선적되거나 또는 수입지에 도착하면 결제 받는 것이 일반적이다. 그런데 그 물품대금의 전액 또는 일부를 후불로 지급받는 조건으로 수출하는 경우가 있는데 이를 연불수출이라 한다. 연불수출은 플랜트 등 대규모 시설재의 수출 시에 주로 채택되고 있다. 영업잉여' WHERE term = '연불수출';
UPDATE term_dictionary SET content = '현재 우리나라를 비롯한 주요 선진국의 실질GDP 추계에 이용하는 물량지수 작성방법이다.' WHERE term = '연쇄가중법';
UPDATE term_dictionary SET content = '수입대금의 전액 또는 일부를 물품 또는 선적서류 영수일로부터 일정 기간이 지난 후에 지급하는 조건의 수입을 말한다. 구매자는 영수한 수입물품을 매각하고 그 대금으로 수입대금을 결제할 수 있으므로 물품대금지급에 대한 부담을 줄일 수 있다.' WHERE term = '연지급수입';
UPDATE term_dictionary SET content = '한 나라 국민이 생산활동에 참여한 결과 발생한 소득은 노동, 자본, 경영 등의 생산요소를 제공한 경제주체에게 나누어진다. 이 중에서 노동을 제공한 대가로 가계에 분배되는 것을 급여 즉 피용자보수라고 하고, 생산활동을 주관한 생산주체의 몫을 영업잉여(operating surplus)라고 한다.' WHERE term = '영업잉여';
UPDATE term_dictionary SET content = '예상손실은 현재 시점부터 일정 기간 동안 발생할 것으로 예상되는 손실의 평균금액을 의미하며 일반적으로 자산별로 발생 가능한 손실액에 발생 확률을 곱하여 산출한다.' WHERE term = '예상손실';
UPDATE term_dictionary SET content = '실시간 총액결제시스템에서는 금융기관의 자금이체 지급지시가 접수되는 즉시 처리되는 것을 원칙으로 하나, 미래의 특정시점에서 자금결제가 이루어지도록 시스템이 금융기관으로부터 미리 자금이체신청을 받아 두었다가 결제시점이 도래하면 자동으로 결제하도록 하는 제도를 예약자금이체제도라 한다.' WHERE term = '예약자금이체제도';
UPDATE term_dictionary SET content = '일본에서 낮은 금리로 엔화를 빌려 외화로 환전한 뒤 해외의 고금리 자산에 투자(일종의 yen carry trade)하는 일본의 중상층 주부 투자자들을 와타나베(Watanabe) 부인이라고 하는데 일본의 개인 외환투자자들을 통칭하는 용어로 확장하여 사용하기도 한다.' WHERE term = '와타나베 부인';
UPDATE term_dictionary SET content = '우리나라는 경제개발 초기에 외화자금이 크게 부족하였고 이에 대응해 국가 차원에서 외화자금을 효율적으로 조달, 운용하기 위해 기업 등의 외환거래를 매우 엄격하게 규제하는 외국환관리법을 시행하였다.' WHERE term = '외국환거래법';
UPDATE term_dictionary SET content = '외국환업무를 업으로 영위하기 위하여 재무건전성, 외환업무시설 및 전문인력을 갖추어 기획재정부장관에게 등록한 금융기관을 “외국환 업무취급기관”이라고 한다.' WHERE term = '외국환업무취급기관/외국환은행';
UPDATE term_dictionary SET content = '자국 통화가치의 안정을 도모하고 투기적인 외화 유출입에 따른 외환시장의 혼란을 방지할 목적으로 정부가 외환시장에 개입하는 데 사용하기 위하여 조성한 기금을 말한다.' WHERE term = '외국환평형기금';
UPDATE term_dictionary SET content = '외국환포지션은 일정시점에서 외국환은행 및 기업 등이 보유하고 있는 외화표시자산과 부채의 차액으로서 거래주체가 환리스크에 노출된 정도를 나타낸다.' WHERE term = '외국환포지션';
UPDATE term_dictionary SET content = '어떤 경제주체의 행위가 본인의 의도와는 관계없이 다른 경제주체에게 의도하지 않은 혜택이나 손해를 발생 시키지만 그 영향에 대한 보상이 이루어지지 않는 현상을 말한다.' WHERE term = '외부효과';
UPDATE term_dictionary SET content = '국제통화기금(IMF)의 외채통계 작성 및 이용 지침에 따르면 외채(external debt) 는 “한나라의 거주자가 비거주자에게 미래 특정 시점에 원금이나 이자 또는 원금 및 이자를 지급해야 하는 우발적이 아닌, 현재에 확정된 채무의 잔액”으로 정의하고 있다.' WHERE term = '외채/대외채권';
UPDATE term_dictionary SET content = '특정 상품의 수출액에서 그 상품 제조를 위한 원자재 수입액을 차감한 잔액을 외화가득액이라 하고, 외화가득액의 수출액에 대한 비율을 외화가득률이라고 한다.' WHERE term = '외화가득액/외화가득율';
UPDATE term_dictionary SET content = '외환결제과정에 내재된 리스크로 국가 간 또는 복수통화 간에 이루어지는 외환결제의 특성상 환율, 시차, 국가 간 상이한 자금이체시스템 및 법률체계 등 여러 요인에 의해 발생한다.' WHERE term = '외환결제리스크';
UPDATE term_dictionary SET content = '외환동시결제(PVP; Payment versus Payment)는 외환결제과정에서 국가 간 결제시간대의 차이로 인하여 발생하는 외환결제리스크를 최소화하기 위하여 외환거래에 따른 수취통화와 지급통화를 동시에 주고 받는 결제방식으로서 대표적으로 CLS은행이 이러한 방식의 외환결제서비스를 제공하고 있다.' WHERE term = '외환동시결제(PVP)';
UPDATE term_dictionary SET content = '외환보유액(Official Reserve Assets)은 중앙은행이나 정부가 국제수지 불균형을 보전하거나 외환시장 안정을 위해 언제든지 사용할 수 있도록 보유하고 있는 교환성이 있고 유동성이나 시장성이 높은 대외지급준비 자산을 말한다.' WHERE term = '외환보유액';
UPDATE term_dictionary SET content = '외환스왑거래란 거래당사자들이 현재의 계약환율에 따라 서로 다른 통화를 교환하고 일정 기간 후 최초 계약시점에서 정한 선물환율에 따라 원금을 재 교환하는 거래를 말한다.' WHERE term = '외환스왑거래';
UPDATE term_dictionary SET content = '외환시장은 좁은 의미에서 외환의 수요와 공급이 연결되는 장소를 말하나 넓은 의미에서는 이러한 장소적 개념뿐만 아니라 외환거래의 형성, 결제 등 외환거래가 정기적 또는 지속적으로 이루어지는 일련의 메커니즘을 포괄한다.' WHERE term = '외환시장';
UPDATE term_dictionary SET content = '요소비용에 의한 국민소득(NI at factor cost)은 통상 국민소득(NI)이라 불리며 한 나라의 국민이 제공한 생산요소에서 발생한 소득의 총액, 즉 노동에 대한 대가인 피용자보수와 토지, 자본, 경영에 대한 대가인 영업잉여의 합계로서 고정자본소모와 순생산 및 수입세가 포함되지 않으므로 한 나라 국민이 벌어들인 순수한 소득을 나타내는 지표이다.' WHERE term = '요소비용 국민소득';
UPDATE term_dictionary SET content = '부적절하거나 잘못된 내부 프로세스(internal process), 인력, 시스템, 외부사건(external events) 등으로 인해 발생할 수 있는 손실 가능성을 말한다.' WHERE term = '운영리스크';
UPDATE term_dictionary SET content = '외환결제리스크 중 가장 대표적인 리스크로 매도통화를 이미 지급하였거나 매도통화의 지급을 취소할 수 없는 상황에서 거래상대방이 파산하는 경우 매입통화를 전액 수취하지 못하는 리스크를 원금리스크(principal risk)라고 한다.' WHERE term = '원금리스크';
UPDATE term_dictionary SET content = '자기자본비율 산출 시 대차대조표상 자산계정의 단순 합계를 분모로 사용할 경우 자산을 구성하는 각 익스포저에 따른 리스크를 반영할 수 없는 문제가 있다.' WHERE term = '위험가중자산/위험가중치';
UPDATE term_dictionary SET content = '유동성(liquidity)이란 자산을 현금으로 전환할 수 있는 정도를 나타내는 용어로 기업의 자산을 필요한 시기에 손실 없이 화폐로 바꿀 수 있는 정도를 나타낸다.' WHERE term = '유동성';
UPDATE term_dictionary SET content = '거래 일방이 일시적인 자금부족으로 인해 정해진 결제 시점에서 결제의무를 이행하지 못함에 따라 거래상대방의 자금조달 계획 등에 악영향을 미치게 되는 위험을 말한다. 유동성 리스크는 거래 상대방이 지급기일이 지난 이후 채무를 결제할 수 있다는 점에서 거래상대방이 파산하여 채권 회수가 영원히 불가능한 신용리스크와 차이가 있으나 실제로는 그 구별이 쉽지 않다.' WHERE term = '유동성리스크';
UPDATE term_dictionary SET content = 'EBRD(European Bank for Reconstruction and Development)는 중동부 유럽국가의 시장경제체제로의 전환 촉진과 경제개발 지원을 목적으로 1991년 3월 설립된 국제금융기구로서 영국 런던에 본부를 두고 있다.' WHERE term = '유럽부흥개발은행(EBRD)';
UPDATE term_dictionary SET content = '유럽연합(EU; European Union)은 1991년 12월 유럽공동체 12개국 정상이 유럽연합 조약(일명 마스트리히트조약)의 체결에 합의한 후 1993년 11월 동 조약이 발효됨에 따라 종전의 유럽공동체(EC; European Communities)를 대신하는 지역공동체로서 1994년 1월 정식 출범하였다.' WHERE term = '유럽연합(EU)';
UPDATE term_dictionary SET content = '유럽연합(EU)의 통화정책을 수행하는 중앙은행으로서 1994년에 설립된 유럽통화기구(EMI)를 승계하여 1998년 6월 출범하였으며 독일 프랑크푸르트에 본부를 두고 있다.' WHERE term = '유럽중앙은행(ECB)';
UPDATE term_dictionary SET content = '유통시장(또는 제2차 시장, secondary market)은 이미 발행된 채권, 주식 등 유가증권이 투자자들 사이에서 매매되는 시장을 말한다.' WHERE term = '유통시장';
UPDATE term_dictionary SET content = '은행권의 위조방지를 위한 장치의 하나로 은행권용지에 삽입된 플라스틱 또는 금속으로 된 가는 선형필름을 말하며, 삽입된 필름의 문양 또는 글자 등을 확인할 수 있다.' WHERE term = '은선';
UPDATE term_dictionary SET content = '이는 영업활동에 의한 이익으로 이자비용을 어느 정도나 부담할 수 있는 지, 즉 기업의 이자부담능력을 평가하는 지표로 이용된다.' WHERE term = '이자보상배율';
UPDATE term_dictionary SET content = '이전소득수지는 국제수지표상 경상수지를 구성하는 항목 중의 하나로 거주자와 비거주자 사이에 무상으로 주고받는 거래의 수지를 말한다. 이러한 거래에는 재외교포가 국내 친지에게 보내는 개인송금, 국외 자선단체의 기부금이나 구호물자, 국제기구 출연금 등이 포함된다.' WHERE term = '이전소득수지';
UPDATE term_dictionary SET content = '국제간 환율 및 금리 전망을 바탕으로 채권발행 통화와 상환 통화를 달리하여 발행하는 채권을 말한다.' WHERE term = '이중통화채(dual currency bond)';
UPDATE term_dictionary SET content = '국채 금융채 회사채 등의 채권은 이자지급 방법에 따라 할인채(discount bond), 이표채(coupon bond), 복리채(compound interest bond) 등으로 구분되는데 이표채는 채권의 권면에 이표(쿠폰 coupon)가 붙어 있어 이자지급일에 이를 떼어 제시함으로써 이자를 지급받는 채권을 말한다.' WHERE term = '이표채';
UPDATE term_dictionary SET content = '점포없이 또는 소수의 영업점만을 두고 인터넷, 모바일, ATM 등 전자매체를 주된 영업채널로 활용하는 온라인 기반의 은행으로서, 이는 은행서비스를 인터넷으로 제공하는 영업방식을 뜻하는 인터넷뱅킹과는 다른 개념이다.' WHERE term = '인터넷전문은행';
UPDATE term_dictionary SET content = '완전경쟁이 이루어질 때 동일한 시기, 동일한 시장에서는 품질이 동일한 상품의 가격이 2개 이상 형성될 수 없다는 법칙이다.' WHERE term = '일물일가의 법칙';
UPDATE term_dictionary SET content = '일중RP제도는 총액결제시스템에서 중앙은행이 참가기관에게 환매조건부증권매매(RP)를 통해 당일 상환을 조건으로 결제에 가용할 수 있는 일중유동성을 제공하는 방법이 다.' WHERE term = '일중RP제도';
UPDATE term_dictionary SET content = '자본거래의 자유화란 직접투자나 간접투자를 불문하고 정부 혹은 민간이 제3 국과의 사이에 자본을 사용 목적, 방법 등에 대해 어떠한 간섭도 받지 않은채 자유롭게 공급 또는 도입하고 나아가 동 자본의 원금과 이자의 상환 등에 제한을 받지 않도록 하는 것, 간단히 말해 국경 간의 자본 이동을 자유화하는 것을 의미한다.' WHERE term = '자본거래자유화';
UPDATE term_dictionary SET content = '증권거래법, 간접투자자산운용업법, 신탁업법 등 자본시장 관련 6개 법률을 통합한 자본시장과 금융투자업에 관한 법률(2009년 2월 시행)을 말한다.' WHERE term = '자본시장통합법';
UPDATE term_dictionary SET content = '경제협력개발기구(OECD)는 설립 직후인 1961년 12월 금융 및 실물 부문에서의 자유로운 거래를 촉진시키기 위하여 양대 자유화규약인 자본이동자유화규약과 경상무역외 거래자유화규약을 제정하였다.' WHERE term = '자본이동자유화규약';
UPDATE term_dictionary SET content = '금융기관이 보유한 자산에 대해 건전성 여부를 분석하여 불건전자산의 발생을 예방하고 이미 발생한 불건전자산에 대하여는 조기 정상화를 촉진함으로써 자산운용의 건전화 도모를 주목적으로 하고 있다.' WHERE term = '자산건전성 분류';
UPDATE term_dictionary SET content = '일반적으로 특수목적기구(special purpose vehicle)가 자산보유자로부터 자산을 양도 신탁 받아 이를 기초로 유동화증권을 발행하고 해당 유동화자산의 관리 운용 처분에 의한 수익이나 차입금으로 유동화증권의 원리금 또는 배당금을 지급하는 일련의 행위를 말한다.' WHERE term = '자산유동화';
UPDATE term_dictionary SET content = '자연독점(natural monopoly)은 생산규모가 커질수록 생산비용이 계속 낮아지는 규모의 경제(economies of scale)가 존재할 때 발생한다.' WHERE term = '자연독점';
UPDATE term_dictionary SET content = '작업증명(proof-of-work)은 제3자로부터의 서비스 요청(request)이 악의적인 공격(spam 또는 DoS, Denial of Service)이 아님을 증명하기 위해서, 자원이 소모되는 작업을 추가로 수행할 것을 요구하는 것을 의미한다.' WHERE term = '작업증명';
UPDATE term_dictionary SET content = '취업자도 아니고 실업자도 아닌 상태로 인해 비경제활동인구로 분류되었지만 취업 가능성과 의사 등을 고려하여 잠재적인 측면에서 경제활동인구로 간주되는 잠재취업가능자와 잠재구직자를 합한 개념이다.' WHERE term = '잠재경제활동인구';
UPDATE term_dictionary SET content = '금융시장은 거래 금융상품의 만기를 기준으로 단기금융시장(money market)과 자본시장(capital market)으로 구분되는데 자본시장은 만기 1년 이상의 장기채권이나 만기가 없는 주식이 거래되는 시장을 말한다.' WHERE term = '장기금융시장(자본시장)';
UPDATE term_dictionary SET content = '국민계정에서 재산소득(property income)이란 금융자산 또는 자연자원(주로 토지 및 지하자원)의 소유주가 타 경제주체에게 자금을 공급하거나 유형 비생산자산을 사용하도록 하고 그 대가로서 수취하는 소득을 말한다.' WHERE term = '재산소득';
UPDATE term_dictionary SET content = '정부의 지출과 조세를 정책수단으로 사용하는 정부의 제반 정책을 일컬어 재정정책이라고 한다.' WHERE term = '재정정책';
UPDATE term_dictionary SET content = '전자단기사채란 자본시장법상의 채무증권으로서 실물이 아닌 전자적으로 발행 유통되는 단기금융상품을 말한다.' WHERE term = '전자단기사채';
UPDATE term_dictionary SET content = '인터넷을 이용하여 가상공간에서 광고, 발주, 수주 등의 상거래 및 대금결제를 수행하는 것을 말한다.' WHERE term = '전자상거래';
UPDATE term_dictionary SET content = '전자지급결제대행(PG; Payment Gateway)이란 인터넷 쇼핑몰 등의 전자상거래에서 구매자로부터 대금을 수취하여 판매자에게 지급될 수 있도록 지급결제정보를 송수신하는 것 또는 그 대가의 정산을 대행하거나 매개하는 것을 의미한다.' WHERE term = '전자지급결제대행';
UPDATE term_dictionary SET content = 'IC카드 등에 화폐가치를 저장하였다가 상품 등의 구매에 사용할 수 있는 전자지급수단으로서 범용성과 환금성을 갖춘 것을 말한다.' WHERE term = '전자화폐';
UPDATE term_dictionary SET content = '전자화폐공동망은 금융기관이 공동으로 개발한 한국형 전자화폐(K-CASH) 이용시 발생한 금융기관 간 정산금액을 결제하기 위한 시스템으로 2000년 7월 가동되었다.' WHERE term = '전자화폐공동망';
UPDATE term_dictionary SET content = '시장실패를 교정하기 위한 정부의 시장개입과 규제가 자원배분의 효율성을 높이기보다 오히려 해치는 경우가 있는데 이를 시장실패에 비유하여 정부실패(government failure)라고 한다.' WHERE term = '정부실패';
UPDATE term_dictionary SET content = '한국전쟁의 여파로 산업활동이 크게 위축되고 물가가 급등하는 등 경제가 큰 혼란에 빠짐에 따라 이를 타개하기 위하여 1953년 2월 15일 화폐단위를 ‘원(圓)’에서 ‘환()’으로 변경하고 100대 1로 절하(100圓 → 1)하는 긴급통화조치를 단행하였다.' WHERE term = '제1차 통화조치';
UPDATE term_dictionary SET content = '제조업 생산능력지수 및 가동률지수는 제조업 부문의 생산능력과 이용 정도를 나타내는 지표이다.' WHERE term = '제조업생산능력/가동률지수';
UPDATE term_dictionary SET content = '전략적 상황에 처한 경제주체들의 행동을 분석하는데 유용하게 활용되는 게임이론의 한 예로서, 협력적인 선택이 양자에게 최선임에도 불구하고 자신의 이익에 치중한 선택으로 인해 오히려 두 사람 모두에게 바람직하지 않은 결과를 가져오는 상황을 말한다.' WHERE term = '죄수의 딜레마';
UPDATE term_dictionary SET content = '주가가 실제 기업의 가치에 비해 고평가되어 있는지, 아니면 저평가되어 있는지 여부를 판단할 때 활용하는 대표적인 지표로 주가수익비율(PER; Price Earning Ratio) 이 있다.' WHERE term = '주가수익비율(PER)';
UPDATE term_dictionary SET content = '중앙거래당사자(CCP; Central Counterparty)는 증권거래 계약의 매도자에 대해 매수자 역할을, 매수자에 대해서는 매도자 역할을 수행하는 기관으로서 다자 간 차감에 의한 청산 업무를 수행하여 결제 유동성을 절약하는 한편 결제이행보증 서비스를 제공하여 참가자의 리스크관리 부담을 경감시키는 역할을 수행하고 있다.' WHERE term = '중앙거래당사자';
UPDATE term_dictionary SET content = '중앙예탁기관(CSD; Central Securities Depository)은 증권예탁 업무를 집중적으로 수행하는 기관으로서, 예탁자 또는 예탁자의 고객으로부터 직간접적으로 증권을 집중 예탁받아 동 예탁증권에 대한 권리를 관리하는 증권예탁제도의 운영기관을 말한다.' WHERE term = '중앙예탁기관';
UPDATE term_dictionary SET content = '일반적으로 중앙은행은 독점적 발권력을 바탕으로 금융기관에 부족자금을 대출하는 은행의 은행 기능과 정부의 세입 및 세출을 관리하고 필요 시 부족자금을 대출하는 정부의 은행 기능을 수행한다.' WHERE term = '중앙은행';
UPDATE term_dictionary SET content = '증권결제리스크는 매매대상 증권의 인도와 대금지급이 예정대로 이행되지 않아 발생할 수 있는 손실가능성을 말하며 원금리스크, 대체비용리스크, 유동성리스크 등으로 구분된다.' WHERE term = '증권결제리스크';
UPDATE term_dictionary SET content = '증권대금동시결제(DVP; Delivery versus Payment)는 중앙예탁기관의 증권결제시스템을 대금결제은행의 자금결제시스템과 연계하여 증권거래시 증권의 실물과 대금을 지급결제 및 시장인프라 위원회(BIS CPMI) 동시에 결제하는 방식이다.' WHERE term = '증권대금동시결제(DVP)';
UPDATE term_dictionary SET content = '국제결제은행(BIS)의 지급결제 및 시장인프라 위원회는 지급결제제도 감시(oversight of payment systems)를 “기존 시스템 및 운영 예정인 시스템을 모니터링하고 동 시스템에 대해 평가하는 한편, 필요 시 개선을 유도함으로써 동 시스템들의 안전성 및 효율성의 증진을 도모하는 중앙은행의 기능”으로 정의하고 있다.' WHERE term = '지급결제제도 감시';
UPDATE term_dictionary SET content = '지니계수란 이탈리아의 통계학자 지니(Gini)가 소득분배상태를 파악하기 위하여 로렌츠곡선의 단점을 보완, 로렌츠곡선이 나타내는 내용을 하나의 단순한 숫자로 표시한 것이 다.' WHERE term = '지니계수';
UPDATE term_dictionary SET content = '지로는 대량수납 및 대량지급거래 등 다수인과의 자금이체를 중계센터를 통해 처리하는 소액대량 지급수단이다.' WHERE term = '지로(GIRO)';
UPDATE term_dictionary SET content = '지방은행공동망은 지방은행의 공동상품인 뱅크라인(Bankline) 업무를 처리하는 공동망으로서 1997년 6월 가동되었다.' WHERE term = '지방은행공동망';
UPDATE term_dictionary SET content = '지수기준년(reference year)은 물량지수=100 또는 명목금액과 실질금액이 동일한 연도를 의미한다. 반면 기준년은 물량지수 계산 시 가격 또는 금액가중치를 제공하는 연도를 말한다. 따라서 고정가중법에서는 기준년과 지수기준년이 동일하나 연쇄가중법에서는 기준년은 직전년도이다.' WHERE term = '지수기준년';
UPDATE term_dictionary SET content = '인접국가나 특정 경제권역내 국가 간에 체결하는 금융협력협정을 말한다.' WHERE term = '지역금융협정';
UPDATE term_dictionary SET content = '직불카드(debit card)는 카드소지인(고객)이 물품이나 서비스를 구매하는 경우 동 카드를 이용하여 판매점에 설치되어 있는 단말기와 카드 발급은행의 주전산기를 통하여 고객의 예금계좌에서 구매대금을 인출하고 이를 판매자의 예금계좌로 자동이체해 주는 용도로 사용되는 카드이다.' WHERE term = '직불카드';
UPDATE term_dictionary SET content = '직접투자는 한 나라의 기업이 국외 현지법인의 경영에 직접 참여하여 영업이익을 획득할 목적으로 자사 보유 자본, 기술 및 인력 등의 생산요소를 국외로 이전하는 거래행위를 말한다.' WHERE term = '직접투자';
UPDATE term_dictionary SET content = '진성어음(commercial bill)이란 기업 간 상거래에 있어 대금결제를 위해 발행되는 어음으로 상업어음, 물품대금어음(물대어음)이라고도 한다.' WHERE term = '진성어음/융통어음';
UPDATE term_dictionary SET content = '만기 시 당초 약정한 환율에 의해 특정 통화를 거래당사자 간에 인도 또는 인수하는 일반적인 선물환거래와 달리 만기에 계약원금의 교환 없이 약정환율과 만기 시 현물환율인 지정환율(fixing rate) 간의 차액만을 지정통화로 결제하는 거래를 말한다.' WHERE term = '차액결제선물환(NDF) 거래';
UPDATE term_dictionary SET content = '결제시스템에 참가하는 금융기관 간 자금결제에서 일정 기간(보통 1일) 동안 발생한 거래의 상호 지급액과 수취액을 모두 상계처리한 다음 그 차액만을 결제하는 시스템으로 양자 간 차액결제시스템과 어음교환, CD, 타행환시스템 등과 같이 다수의 금융기관 간에 이루어지는 다자 간 차액결제시스템으로 구분된다.' WHERE term = '차액결제시스템';
UPDATE term_dictionary SET content = '차입매수(LBO; Leveraged Buy out)란 기업을 매수하려는 주체가 인수에 필요한 자금이 충분하지 않은 경우 금융기관 등으로부터 인수대상 기업의 자산을 담보로 인수자금을 차입하여 기업을 매수하는 방식을 말한다.' WHERE term = '차입매수(LBO)';
UPDATE term_dictionary SET content = '라틴어로 ‘지체하다’란 뜻의 ‘morari’에서 파생된 말로, 한 국가가 경제 정치적인 이유로 외국에서 빌려 온 차관에 대해 일시적으로 상환을 연기하는 ‘지불유예(支拂猶豫) ’를 말한다.' WHERE term = '채무상환유예(moratorium)';
UPDATE term_dictionary SET content = '청년실업률이란 15세에서 29세에 해당하는 청년층의 경제활동인구 중 실업자의 비율을 말한다.' WHERE term = '청년실업률';
UPDATE term_dictionary SET content = '자금결제에 있어 청산(clearing)은 경제주체 간 지급행위가 수표, 계좌이체 등 비현금수 단을 이용하여 이루어진 경우 지급인과 수취인의 거래은행들이 주고 받을 금액을 정산하고 최종 확정하는 과정을 말한다.' WHERE term = '청산';
UPDATE term_dictionary SET content = '기업에서는 지속적인 생산능력을 유지하고 경쟁력을 확보하기 위해 노후설비를 새로운 설비로 대체하거나 신규 사업 진출을 위해 공장도 짓고 기계도 구매하는데 이러한 경제활동은 해당연도의 이익만을 위한 것이 아니고 미래의 지속적인 수입의 보장 등 장기적인 안목에서 이루어진다.' WHERE term = '총고정자본형성';
UPDATE term_dictionary SET content = '주택담보대출 차주의 원리금상환능력을 감안하여 주택담보대출 한도를 설정하기 위해 도입된 규제 비율이다.' WHERE term = '총부채상환비율(DTI)';
UPDATE term_dictionary SET content = '일반적으로 어음 수표소지인이 거래은행에 어음 수표대금 회수를 위임하고 동 위임을 받은 거래은행은 어음 수표 발행점포 앞으로 동 대금의 지급을 요청하는 일련의 절차를 말한다.' WHERE term = '추심';
UPDATE term_dictionary SET content = '출금이체(debit transfer)는 수취인이 자신이 거래하는 금융기관에 추심을 의뢰하여 (즉, 인출지시) 지급인의 계좌로부터 이체금액을 출금하여 수취인 자신의 계좌에 입금하도록 하는 계좌이체방식을 말한다.' WHERE term = '출금이체';
UPDATE term_dictionary SET content = '치킨게임(chicken game)은 다양한 분야에서 이해 당사자가 모두 최악의 상황에 직면할 가능성을 초래하는 극단적인 경쟁을 가리키는 용어로 쓰이고 있다.' WHERE term = '치킨게임';
UPDATE term_dictionary SET content = '카르텔(cartel)이란 동종 혹은 유사 산업에서 경쟁하는 기업들이 상호 간의 경쟁을 제한하고 완화함으로써 시장을 지배할 목적으로 결성한 기업연합체를 말한다.' WHERE term = '카르텔';
UPDATE term_dictionary SET content = '커버드본드(covered bond)란 금융기관이 부동산 담보대출 등 자신이 보유한 고정자산을 담보로 발행한 채권을 말하며 2014년 4월 도입되었다.' WHERE term = '커버드본드(이중상환청구권부 채권)';
UPDATE term_dictionary SET content = '코리보(KORIBOR)는 국내 은행들이 서로 자금거래를 할 때 기준이 되는 금리를 말한다.' WHERE term = '코리보';
UPDATE term_dictionary SET content = '콜(call)시장은 금융기관들이 일시적인 자금 과부족을 조절하기 위하여 상호 간에 초단기로 자금을 차입하거나 대여하는 시장이다.' WHERE term = '콜시장';
UPDATE term_dictionary SET content = '타행환공동망은 금융공동망 중계센터인 금융결제원과 금융기관들의 전산시스템을 상호 연결하여 송금인과 수취인의 거래은행이 다르더라도 전국 어느 금융기관의 점포에서나 송금업무를 처리할 수 있게 한 시스템으로 1989년 12월 가동되었다.' WHERE term = '타행환공동망';
UPDATE term_dictionary SET content = '탄소배출권(CERs; Certified Emission Reductions)은 온실가스를 일정기간 동안 배출할 수 있는 권리를 말한다.' WHERE term = '탄소배출권';
UPDATE term_dictionary SET content = '미국 예일대학교의 제임스 토빈(James Tobin) 교수가 1978년에 주장한 것으로 국제 투기자본(핫머니)의 급격한 자금유출입으로 각국의 통화가치가 급등락하여 통화위기가 촉발되는 것을 막기 위한 국경간 자본이동 규제방안의 하나이다.' WHERE term = '토빈세(Tobin tax)';
UPDATE term_dictionary SET content = '통합발행제도(fungible issue 또는 reopening issue)란 일정 기간(3개월, 6개월, 1 년 등) 동안 계속해서 발행하는 채권의 표면금리와 만기 등 발행조건을 일치시켜 그 기간 동안 발행한 채권을 동일한 채권으로 만드는 제도이다.' WHERE term = '통합발행제도';
UPDATE term_dictionary SET content = '통화스왑이란 외환스왑과 마찬가지로 거래당사자간에 서로 다른 통화를 교환하고 일정 기간 후 원금을 재 교환하기로 약정하는 거래를 말한다.' WHERE term = '통화스왑';
UPDATE term_dictionary SET content = '통화안정증권은 한국은행법 제69조 및 한국은행 통화안정증권법에 따라 한국은 행이 유동성 조절을 목적으로 발행하는 채무증서이다.' WHERE term = '통화안정증권';
UPDATE term_dictionary SET content = '중앙은행은 역사적으로 경제구조의 변화, 금융시장의 발달 정도 등에 따라 다른 형태의 통화정책 운영체제를 도입해 왔다.' WHERE term = '통화정책 운영체제(monetary policy regime)';
UPDATE term_dictionary SET content = '각 산업부문이 재화나 서비스의 생산에 사용하기 위하여 다른 산업으로부터 구매한 원재료, 연료 등 중간재별 투입액을 총투입액으로 나눈 것으로서 각 부문 생산물 1단위 생산에 필요한 중간재들의 단위를 나타낸다.' WHERE term = '투입계수';
UPDATE term_dictionary SET content = '투자은행(investment bank)이란 상업은행(commercial bank)에 대비되는 개념으로 상업은행이 예금을 바탕으로 기업에 자금을 공급하는 전통적 은행업에 주력했다면 투자은행은 유가증권 인수를 통한 자금 공급을 주업으로 한다.' WHERE term = '투자은행';
UPDATE term_dictionary SET content = '자산유동화증권(ABS; Asset-Backed Securities) 발행에는 자산보유자, 특수목적기구(SPV), 자산관리자 및 신용평가기관 등이 참가하게 된다.' WHERE term = '특수목적기구(SPV)';
UPDATE term_dictionary SET content = '자원배분이 가장 효율적으로 이루어진 상태여서 더 이상의 개선 여지가 없는 상황을 의미한다.' WHERE term = '파레토최적';
UPDATE term_dictionary SET content = '페더럴펀드(federal funds)는 미 연방준비은행에 지급준비금 예치의무가 있는 예금은행이 지급준비금 과부족을 조절하기 위해 여타 예금은행, 정부보증기관(government-sponsored enterprises) 등으로부터 무담보로 차입한 자금을 말한다.' WHERE term = '페더럴펀드';
UPDATE term_dictionary SET content = '프로젝트 파이낸싱(PF; Project Financing)이란 석유개발, 탄광채굴, 조선소, 발전소, 고속도로 건설 등 대규모 사업을 추진하는 경우 그 프로젝트에 필요한 대규모의 소요자금과 각종 금융수요를 충족하기 위해서 동원되는 다수의 금융수단이나 투자금융기법을 통칭하는 말이다.' WHERE term = '프로젝트 파이낸싱';
UPDATE term_dictionary SET content = '1920년대 미국의 경제학자 어빙 피셔(Irving Fisher)가 발표한 이론으로, 피셔방정식(fisher equation)은 명목금리가 실질금리와 기대인플레이션의 합계와 같다고 표현한다.' WHERE term = '피셔효과';
UPDATE term_dictionary SET content = '한 나라 국민이 생산활동에 참여한 결과 발생한 소득은 노동, 자본, 경영 등의 생산요소를 제공한 경제주체에 나누어진다. 이 중에서 노동을 제공한 대가로 가계에 분배되는 것을 급여 즉 피용자보수(compensation of employees)라고 하고, 생산활동을 주관한 생산주체의 몫을 영업 잉여라고 한다.' WHERE term = '피용자보수';
UPDATE term_dictionary SET content = '어떤 상품이나 서비스의 소비를 한 단위 늘림에 따라 추가로 증가한 효용을 한계효용이라 한다. 한계효용은 총효용의 변화분을 소비량의 변화분으로 나눔으로써 계산할 수 있다. 일반적으로 소비량이 증가함에 따라 전체 효용은 증가하지만, 한계효용은 그 크기가 점차 줄어든다(한계효용체감의 법칙).' WHERE term = '한계효용';
UPDATE term_dictionary SET content = '우리나라의 중앙은행인 한국은행은 1950년 6월 12일 한국은행법에 의하여 설립되었다.' WHERE term = '한국은행';
UPDATE term_dictionary SET content = '한국은행이 금융기관 간 자금결제를 위하여 1994년 12월부터 가동 운영하고 있는 거액결제시스템으로 금융기관의 콜거래, 외환 및 증권매매 등에 따른 원화자금 결제는 대부분 한은금융망을 이용하여 한국은행에 개설된 당좌예금을 계좌이체하는 방식으로 처리한다.' WHERE term = '한은금융망(BOK-Wire+)';
UPDATE term_dictionary SET content = '개인을 대상으로 모집한 자금을 고수익 또는 위험회피 등을 목적으로 국제증권시장이나 국제외환시장에 투자하는 사적투자조합 또는 투자계약을 말한다.' WHERE term = '헤지펀드';
UPDATE term_dictionary SET content = '현금자동인출기(CD)공동망은 금융공동망 중계센터인 금융결제원과 금융기관들의 전산시스템을 상호 연결하여 특정 금융기관 고객이 다른 금융기관의 CD 또는 ATM을 이용하여 현금인출, 계좌이체, 잔액조회 등의 서비스를 받을 수 있도록 구축된 시스템으로 1988년 7월 가동되었다.' WHERE term = '현금자동인출기(CD)공동망';
UPDATE term_dictionary SET content = '현지금융이란 거주자(개인은 제외), 거주자의 국외지점 및 현지법인이 외국에서 사용하기 위하여 외국에서 외화자금을 차입(증권발행에 의한 경우 포함)하거나 지급보증을 받는 것을 말한다.' WHERE term = '현지금융';
UPDATE term_dictionary SET content = '혼합형결제시스템(hybrid settlement system)은 지급지시가 영업시간중에 실시간으로 결제되어 신용리스크가 제거되는 실시간총액결제방식의 장점과 결제유동성을 절약할 수 있는 차액결제방식의 장점이 결합된 지급결제시스템을 말한다.' WHERE term = '혼합형결제시스템';
UPDATE term_dictionary SET content = '한국은행이 발행하여 시중에서 유통되는 화폐는 예금 또는 세금 납부 등으로 금융기관으로 입금되며, 금융기관은 입금된 화폐 중 일부를 고객의 예금인출에 대비하여 시재금으로 보유하고 나머지는 한국은행에 예금지급준비금과 결제자금 등으로 입금하는데, 이처럼 한국은행에서 발행된 화폐가 다시 한국은행으로 되돌아 들어오는 것을 화폐의 환수라 한다.' WHERE term = '화폐환수';
UPDATE term_dictionary SET content = '환경계정이란 1993년 UN이 경제활동과 환경 간의 상호 관계를 체계적으로 분석하기 위하여 국민계정의 위성계정 형태로 새로 도입한 환경경제통합계정(SEEA; System of Integrated Environmental and Economic Accounts)을 말한다.' WHERE term = '환경계정';
UPDATE term_dictionary SET content = '장래의 예상하지 못한 환율변동으로 인하여 기업 등이 보유하고 있는 외화표시 순자산(자산-부채)의 가치 또는 현금흐름의 순가치가 변동될 수 있는 불확실성을 제거하는 것을 의미한다.' WHERE term = '환리스크헤지';
UPDATE term_dictionary SET content = '1988년에 제정된 미국의 종합무역법에서 규정된 개념으로 동 법은 현저한 대미 무역흑자 및 상당한 경상수지 흑자를 보인 국가를 환율조작국으로 지정할 수 있다.' WHERE term = '환율조작국';
UPDATE term_dictionary SET content = '환위험은 크게 회계적 환위험(또는 환산환위험)과 거래적 환위험으로 나누는데, 이 중에서도 회계적 환위험이란 해외지사 및 자회사의 재무제표를 모기업의 재무제표와 연결시키기 위해 자산과 부채의 가치를 동일한 통화로 환산하는 과정에서 발생하는 환위험을 말한다.' WHERE term = '환차손/환차익';
UPDATE term_dictionary SET content = '개별 경제지표로는 파악하기 어려운 국민경제의 총체적인 경기수준을 파악하기 위하여 경기종합지수를 작성한다.' WHERE term = '후행종합지수';
UPDATE term_dictionary SET content = '1988년 6월 바젤은행감독위원회(BCBS)가 발표한 바젤자기자본협약(Basel Capital Accord)에 따른 자본규제(바젤Ⅰ) 비율을 의미한다.' WHERE term = 'BIS 자기자본비율';
UPDATE term_dictionary SET content = '은행의 경영실태평가방식으로는 CAMEL-R, ROCA 및 CACREL 시스템이 있는데, 일반은행 본점 및 현지법인에 대해서는 CAMEL-R시스템, 외은지점 및 국내은행 국외지점에 대해서는 ROCA시스템, 특수은행에 대해서는 CACREL시스템에 의해 평가한다.' WHERE term = 'CAMEL-R시스템/ROCA시스템/CACREL시스템';
UPDATE term_dictionary SET content = 'CLS은행은 외환결제리스크 감축에 관한 국제결제은행(BIS)의 권고에 따라 1999 년 주요 국제 상업은행들이 세계 외환거래의 동시결제를 구현할 목적으로 설립한 국제외환결제전문은행이다.' WHERE term = 'CLS은행';
UPDATE term_dictionary SET content = 'CMO(Collateralized Mortgage Obligation)는 미국에서 발행되는 주택담보대출 증권의 일종으로서 pass-through 및 모기지를 기초자산으로 하여 투자자의 다양한 선호에 부합되도록 기초자산으로부터 유입되는 현금흐름이 만기, 이자율 및 조기상환 민감도가 상이한 몇 개의 tranche로 나누어 구조화한 상품이다.' WHERE term = 'CMO';
UPDATE term_dictionary SET content = '특정 금융업권(은행)의 부도 충격이 거래상대방과의 상호거래 익스포저를 통해 순차적으로 확산되어 나타나는 손실 합계가 전체 금융(은행)부문 운용 자산에서 차지하는 비중(Battiston et al,. 2012)으로, 이 값이 클수록 부도충격의 전염도가 높아짐을 의미한다.' WHERE term = 'DebtRank';
UPDATE term_dictionary SET content = '중앙은행은 통화정책수단을 사용하여 금리나 통화량에 영향을 미치고 나아가 물가안정, 금융안정 등을 달성함으로써 경제가 지속 가능한 성장을 이룰 수 있도록 한다.' WHERE term = 'EC방식';
UPDATE term_dictionary SET content = '영국의 FTSE 인터내셔널사가 작성, 발표하는 세계 주가지수를 말하며 ‘FT 지수’라고도 한다.' WHERE term = 'FTSE 지수';
UPDATE term_dictionary SET content = 'G7에 속하는 7개국, 신흥시장국 12개국 및 유럽연합을 포함한 20개국의 국제회의체이다.' WHERE term = 'G20(Group of 20)';
UPDATE term_dictionary SET content = '국제통화기금(IMF) 회원국 쿼타에서 IMF가 보유하고 있는 해당 회원국 통화를 차감한 부분을 말하며 IMF 리저브포지션(Reserve Position) 또는 리저브트란셰(Reserve Tranche)라고도 한다.' WHERE term = 'IMF 포지션';
UPDATE term_dictionary SET content = '이론적으로 환율이 상승할 경우 수출은 늘어나고 수입은 줄어들어 경상수지가 개선된다.' WHERE term = 'J커브효과';
UPDATE term_dictionary SET content = '환율이 특정 구간(barrier)에 도달하는 경우 옵션이 발효(KI; Knock-In)되거나 소멸(KO; Knock-Out)되는 조건이 부과된 비정형적인 통화옵션 거래의 일종이다.' WHERE term = 'KIKO';
UPDATE term_dictionary SET content = '미국의 모건스탠리 캐피털 인터내셔널(Morgan Stanley Capital International)사가 작성, 발표하는 세계 주가지수를 말한다.' WHERE term = 'MSCI 지수';
UPDATE term_dictionary SET content = 'N-B SRS(Network-Based Systemic Risk Scoring)은 특정은행의 도산확률이 여타 은행과의 상호거래 익스포저를 통해 확대되어 나타나는 리스크 총량으로, 개별은행의 도산확 ABC PF-ABCP 률과 거래상대방과의 상호거래 규모를 곱한 값의 제곱근으로 정의한다(Das, 2015).' WHERE term = 'N-B SRS';
UPDATE term_dictionary SET content = 'P2P대출(peer-to-peer lending)은 온라인상에서 자금공급자(투자자)와 자금수요자(차입자) 간 전통적인 금융회사의 중개 없이 자금중개가 이뤄지는 금융활동의 하나이다.' WHERE term = 'P2P대출';
UPDATE term_dictionary SET content = 'TED 스프레드는 원래 미국 단기국채(T-Bill) 선물금리와 유로달러 선물금리 간 차이로, 영문 약어 TED는 T-bill의 ‘T’와 유로달러 선물을 의미하는 ‘ED’에서 유래하였다.' WHERE term = 'TED 스프레드';
UPDATE term_dictionary SET content = '주어진 신뢰수준 하에서 일정 기간 동안 발생할 수 있는 ‘최대 손실금액’으로 금융기관의 잠재적인 손실을 측정하는 지표이다. 예를 들어 목표기간 1년, 신뢰수준 95%에서 산출된 VaR가 10억 원이라면 이는 1년 동안 발생할 수 있는 손실금액이 10억 원보다 작을 확률이 95%라는 것을 의미한다.' WHERE term = 'VaR(Value at Risk)';
